INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7903, 434986, 'tt5563862', NULL, 'Replace', 'Replace', 'movie', 2017, 'https://image.tmdb.org/t/p/w500/5pYnf8a9Plaqwfny6lfk5Bpzgo8.jpg', 'https://image.tmdb.org/t/p/original/AfvScEfjWRdVdicFXdbE0MPhNgG.jpg', 'Kira''s skin starts to age rapidly, dry out and crumble away. But then she discovers that she can replace her own skin with somebody else''s.', NULL, NULL, 1.027, 4.971, 0, 1.01, '2026-08-07 03:39:39', '2026-08-07 03:39:39');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7904, 1034250, NULL, NULL, 'Everyday makeup (I feel fantastic)', 'Everyday makeup (I feel fantastic)', 'movie', 2019, 'https://image.tmdb.org/t/p/w500/v0s10My8W6SFQCxuq54bBfQ9bHE.jpg', NULL, 'In facing the lens and addressing an intangible audience, the face on the  web becomes a disturbing mirror of its own growing dehumanization.  Everyday makeup dissects this artificial mask by discovering the raw and  pulsating matter of which it is made. The digital image is gutted and broken  down, finally revealing its atom, its pure essence: the pixel.  This autopsy process of the internettian non-body thus allows us to go back  to an aesthetic root in which thought is not filtered and in which entertainment  is reduced to an inevitable colored chaos.', NULL, NULL, 0.2863, 0.0, 0, 1.04, '2026-08-07 03:39:39', '2026-08-07 03:39:39');
