INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7924, 155084, 'tt2059171', NULL, '13 Sins', '13 Sins', 'movie', 2014, 'https://image.tmdb.org/t/p/w500/x4tC1s6oFG9nEyxVSM0FiIsLea1.jpg', 'https://image.tmdb.org/t/p/original/67WVW36tcLYnY2ONzbxh7gEfohh.jpg', 'Drowning in debt as he''s about to get married, a bright but meek salesman receives a mysterious phone call informing him that he''s on a hidden-camera game show where he must execute 13 tasks to receive a multi-million dollar cash prize.', NULL, NULL, 6.6235, 6.316, 0, 11.01, '2026-08-07 03:39:39', '2026-08-07 03:39:39');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7925, 31139, 'tt0076727', NULL, 'Office Romance', 'Служебный роман', 'movie', 1977, 'https://image.tmdb.org/t/p/w500/21TgZRiA5gDlyCwQEyYqZcqwMgN.jpg', 'https://image.tmdb.org/t/p/original/qnALlAgoQu6rDVKsuFJ7WDvLQjm.jpg', 'Anatoly Novoseltsev is a mousy single father and office stumblebum working at a statistics bureau in Moscow. In the hopes of being promoted, he is coaxed into charming his disagreeable and seemingly unfeeling boss, Ludmila Kalugina, or "Meany" as she''s otherwise known by her subordinates. Helped by his colleagues Olya and Yura, Anatoly attempts to ease the yoke of Ms. Kalugina, and what follows in the wake of his graceless manoeuvres is completely unforeseen, as he awakens a side to her not yet known, even to herself..', NULL, NULL, 1.6715, 7.845, 0, 11.01, '2026-08-07 03:39:39', '2026-08-07 03:39:39');
