INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7956, 4620, 'tt0796264', NULL, 'Eureka', 'Eureka', 'tv', 2006, 'https://image.tmdb.org/t/p/w500/f2l5hUk63hPqYTucnFy2HmElFV0.jpg', 'https://image.tmdb.org/t/p/original/8MQeyFsWrp2ILjbumtxrinmk7t4.jpg', 'The sleepy Pacific Northwest town of Eureka is hiding a mysterious secret. The government has been relocating the world''s geniuses and their families to this rustic town for years where innovation and chaos have lived hand in hand. U.S. Marshal Jack Carter stumbles upon this odd town after wrecking his car and becoming stranded there. When the denizens of the town unleash an unknown scientific creation, Carter jumps in to try to restore order and consequently learns of one of the country''s best kept secrets.', NULL, NULL, 21.0218, 7.747, 0, 1.05, '2026-08-07 03:39:39', '2026-08-07 03:39:39');
