INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7960, 96580, 'tt8690918', NULL, 'Resident Alien', 'Resident Alien', 'tv', 2021, 'https://image.tmdb.org/t/p/w500/5van3ktOTqWr5lcixh5aR8NlqqW.jpg', 'https://image.tmdb.org/t/p/original/aCbOj4wc6vQUUVNKppssj2PYUy0.jpg', 'Crash-landed alien Harry takes on the identity of a small-town Colorado doctor. Arriving with a secret mission, he starts off living a simple life…but things get a bit rocky when he’s roped into solving a local murder and realizes he needs to assimilate into his new world. As he does, he begins to wrestle with the moral dilemma of his mission and asking the big life questions like: “Are human beings worth saving?” and “Why do they fold their pizza before eating it?”', NULL, NULL, 37.6516, 7.788, 0, 3.04, '2026-08-07 03:39:39', '2026-08-07 03:39:39');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7961, 88989, 'tt8760932', NULL, 'Nine Perfect Strangers', 'Nine Perfect Strangers', 'tv', 2021, 'https://image.tmdb.org/t/p/w500/oPcqsZIFHrv7HoGgFQnsGDiPulD.jpg', 'https://image.tmdb.org/t/p/original/RzCw9LQyAcoa9mn4xkEAyuvhgr.jpg', 'At a boutique health-and-wellness resort that promises healing and transformation, nine stressed city dwellers try to get on a path to a better way of living. Watching over them during this 10-day retreat is the resort''s director, Masha, a woman on a mission to reinvigorate their tired minds and bodies. However, these nine "perfect" strangers have no idea what is about to hit them.', NULL, NULL, 14.0244, 6.903, 0, 1.02, '2026-08-07 03:39:39', '2026-08-07 03:39:39');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7962, NULL, NULL, 303813, 'Silent Hill 2: Deluxe Edition', 'Silent Hill 2: Deluxe Edition', 'game', 2024, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coavag.jpg', NULL, 'Silent Hill 2 Remake is a ground-up reimagining of the 2001 psychological horror game. It follows James Sunderland as he searches for his deceased wife in the fog-shrouded town of Silent Hill. The remake features entirely rebuilt visuals in Unreal Engine 5, over-the-shoulder gameplay, reworked combat, and new voice acting.

The Deluxe Edition contains the main game, a digital artbook, the digital soundtrack, and Pyramid Head Mask (pizza box).', 'https://www.igdb.com/games/silent-hill-2-deluxe-edition', '["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, NULL, 0, 1.01, '2026-08-07 03:39:39', '2026-08-07 03:39:39');
