INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7976, 11025, 'tt0363282', NULL, 'New York Minute', 'New York Minute', 'movie', 2004, 'https://image.tmdb.org/t/p/w500/px9hV6w6XzAjGdxCRUAUasAHQsP.jpg', 'https://image.tmdb.org/t/p/original/13UkK69iyMsB45H2p1WPXJPS87w.jpg', 'Honors student Jane Ryan heads to Manhattan for a college-scholarship competition. Her rebellious twin Roxy tags along to crash a video shoot. But anything can happen – and does – in a romp involving a pursuing truant officer, a smuggler, hunkalicious guys, and the girls'' realization that when the chips are down, a sister can be the best friend of all.', NULL, NULL, 3.7509, 6.142, 0, 1.07, '2026-08-07 03:39:39', '2026-08-07 03:39:39');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7977, 96402, 'tt11428630', NULL, 'BOFURI: I Don''t Want to Get Hurt, so I''ll Max Out My Defense.', '痛いのは嫌なので防御力に極振りしたいと思います。', 'tv', 2020, 'https://image.tmdb.org/t/p/w500/fdcMiknnRcmVgWb9wGS9TxE06cG.jpg', 'https://image.tmdb.org/t/p/original/lkuMXv7M2NMmcErLmBgvLIslJ23.jpg', 'Kaede Honjou is invited by her friend Risa Shiramine to play a virtual reality MMO game with her. While Kaede doesn''t dislike games, what she really, truly dislikes is being in pain. She creates a character named Maple, and decides to put all her points in VIT to minimize pain. As a result, she moves slowly, can''t use magic, and even a rabbit can get the best of her. But as it turns out, she acquires a skill known as "Absolute Defense" as a result of her pumping points into VIT, as well as a "Counter Skill" that works against special moves. Now, with her ability to nullify all damage, she goes on adventures.', NULL, NULL, 14.6527, 7.455, 0, 1.03, '2026-08-07 03:39:39', '2026-08-07 03:39:39');
