INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7980, 582871, 'tt7969836', NULL, 'The Twentieth Century', 'The Twentieth Century', 'movie', 2019, 'https://image.tmdb.org/t/p/w500/q7JE9x0By5AWi8RnIIEX6F8m4Zh.jpg', 'https://image.tmdb.org/t/p/original/h5h0IH5iFURX3ahzH4wecVBnwjw.jpg', 'Toronto, Canada, 1899. William Lyon Mackenzie King (1874-1950) fervently believes that he is destined to become Prime Minister, but to do so he will first have to fight his personal obsessions and overcome the many obstacles he will encounter on his tortuous path to power.', NULL, NULL, 0.9125, 6.269, 0, 1.03, '2026-08-07 03:39:39', '2026-08-07 03:39:39');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7981, 537655, 'tt6284064', NULL, 'The Bears'' Famous Invasion of Sicily', 'La Fameuse Invasion des ours en Sicile', 'movie', 2019, 'https://image.tmdb.org/t/p/w500/tmSLN2bNCQ8fEex3rEw7GobJP3Z.jpg', 'https://image.tmdb.org/t/p/original/8NE6VgSJ2Dx0fQm1UxY9KVt9fLm.jpg', 'Tonio, the son the bears King, is kidnapped by hunters in the Sicilian mountains. Due to the harshness of a winter that threatens famine, the Bear King decides to invade the land of men (in the hope of finding his son). Thanks to his powerful army and the help of a wizard, while he will succeed at both quests, he will soon find out that bears are not meant to live among men.', NULL, NULL, 1.7516, 7.2, 0, 1.02, '2026-08-07 03:39:39', '2026-08-07 03:39:39');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7982, 56289, 'tt1315388', NULL, 'Machotaildrop', 'Machotaildrop', 'movie', 2009, 'https://image.tmdb.org/t/p/w500/fPNdZxJHHHLs7zmLRoDZm86maul.jpg', NULL, 'Walter Rhum, an amateur skateboarder, realizes his dream of turning pro and riding for the world''s greatest skateboard company, Machotaildrop. Set in an anachronistic time and place, Machotaildrop is the greatest skateboard company of its day and the regal and grand sport of skateboarding has been thriving for many generations. Walter''s journey serves as a window through which we discover the dark underbelly of what appears at first to be a benign skateboard company.', NULL, NULL, 0.7391, 5.7, 0, 1.02, '2026-08-07 03:39:39', '2026-08-07 03:39:39');
