INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7984, 268228, 'tt0100638', NULL, 'Slow Bob in the Lower Dimensions', 'Slow Bob in the Lower Dimensions', 'movie', 1991, 'https://image.tmdb.org/t/p/w500/2jyJsGfuDQOSOBVosCk9TbS4MES.jpg', 'https://image.tmdb.org/t/p/original/o6A1zT0HThe4TE1pPluMLACzO1U.jpg', 'Nightmarish pilot about Robert Potemkin, a man with deformed back, who lives in the attic of his family''s house. One night, his siamese sisters plan a prank on him, but sentient lizards send him to a parallel world to save photo-people.', NULL, NULL, 0.6476, 7.083, 0, 1.02, '2026-08-07 03:39:39', '2026-08-07 03:39:39');
