INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7986, 274855, 'tt1981128', NULL, 'Geostorm', 'Geostorm', 'movie', 2017, 'https://image.tmdb.org/t/p/w500/nrsx0jEaBgXq4PWo7SooSnYJTv.jpg', 'https://image.tmdb.org/t/p/original/vIEuJiIZN9EclAJDmD49F2zUzuX.jpg', 'After an unprecedented series of natural disasters threatened the planet, the world''s leaders came together to create an intricate network of satellites to control the global climate and keep everyone safe. But now, something has gone wrong: the system built to protect Earth is attacking it, and it becomes a race against the clock to uncover the real threat before a worldwide geostorm wipes out everything and everyone along with it.', NULL, NULL, 11.2926, 6.125, 0, 1.08, '2026-08-07 03:39:39', '2026-08-07 03:39:39');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7987, 575265, 'tt9603208', NULL, 'Mission: Impossible - The Final Reckoning', 'Mission: Impossible - The Final Reckoning', 'movie', 2025, 'https://image.tmdb.org/t/p/w500/iKPsC9EFUafRP9SrUznI61getVP.jpg', 'https://image.tmdb.org/t/p/original/538U9snNc2fpnOmYXAPUh3zn31H.jpg', 'Ethan Hunt and team continue their search for the terrifying AI known as the Entity — which has infiltrated intelligence networks all over the globe — with the world''s governments and a mysterious ghost from Hunt''s past on their trail. Joined by new allies and armed with the means to shut the Entity down for good, Hunt is in a race against time to prevent the world as we know it from changing forever.', NULL, NULL, 31.1247, 7.175, 0, 1.02, '2026-08-07 03:39:39', '2026-08-07 03:39:39');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7988, 2102, 'tt0100649', NULL, 'Solar Crisis', 'Solar Crisis', 'movie', 1992, 'https://image.tmdb.org/t/p/w500/Hbv6CPtv4ehgE60dXOYKmIrcV1.jpg', 'https://image.tmdb.org/t/p/original/2DALChI060gUghE96J9KP7RcgLb.jpg', 'A huge solar flare is predicted to fry the Earth. Astronauts aboard the spaceship Helios must go to the Sun to drop a bomb equipped with an Artificial Intelligence and a Japanese pilot at the right time so the flare will point somewhere else.', NULL, NULL, 1.7878, 4.459, 0, 1.02, '2026-08-07 03:39:39', '2026-08-07 03:39:39');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7989, 5551, 'tt0186566', NULL, 'Space Cowboys', 'Space Cowboys', 'movie', 2000, 'https://image.tmdb.org/t/p/w500/hPzt1bbA1sUDQOl6Vujmyz2hjLN.jpg', 'https://image.tmdb.org/t/p/original/sUye6BrOjlpoAKRMjcP0YwiUvHW.jpg', 'Frank Corvin, ‘Hawk’ Hawkins, Jerry O''Neill and ‘Tank’ Sullivan were hotdog members of Project Daedalus, the US Air Force''s test program for space travel, but their hopes were dashed in 1958 with the formation of NASA and the use of trained chimps. They blackmail their way into orbit when Russia''s mysterious ‘Ikon’ communications satellite''s orbit begins to degrade and threatens to crash to Earth.', NULL, NULL, 6.7543, 6.39, 0, 1.03, '2026-08-07 03:39:39', '2026-08-07 03:39:39');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7990, 40160, 'tt0079550', NULL, 'Meteor', 'Meteor', 'movie', 1979, 'https://image.tmdb.org/t/p/w500/xMUuS1KFHRTFSf3PAY2tsbBdqkL.jpg', 'https://image.tmdb.org/t/p/original/fqWjR25Vo0VZbYDGC2OLfA69GH1.jpg', 'After a collision with a comet, a nearly 8km wide piece of the asteroid "Orpheus" is heading towards Earth. If it hits, it will cause an incredible catastrophe that will probably extinguish mankind. To stop the meteor, NASA wants to use the illegal nuclear weapon satellite "Hercules," but discovers soon that it doesn''t have enough firepower. Their only chance to save the world is to join forces with the USSR, which has also launched such an illegal satellite. But will both governments agree?', NULL, NULL, 1.9653, 5.2, 0, 2.015, '2026-08-07 03:39:39', '2026-08-07 03:39:39');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7991, 8656, 'tt0120647', NULL, 'Deep Impact', 'Deep Impact', 'movie', 1998, 'https://image.tmdb.org/t/p/w500/a3vQS7JKqlOb3MdVJHuTCP9s7Mg.jpg', 'https://image.tmdb.org/t/p/original/pWmJBkdb0EMb3PSd2f9wjza0krb.jpg', 'A seven-mile-wide space rock is hurtling toward Earth, threatening to obliterate the planet. Now, it''s up to the president of the United States to save the world. He appoints a tough-as-nails veteran astronaut to lead a joint American-Russian crew into space to destroy the comet before impact. Meanwhile, an enterprising reporter uses her smarts to uncover the scoop of the century.', NULL, NULL, 16.2827, 6.243, 0, 2.02, '2026-08-07 03:39:39', '2026-08-07 03:39:39');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7992, 524047, 'tt7737786', NULL, 'Greenland', 'Greenland', 'movie', 2020, 'https://image.tmdb.org/t/p/w500/bNo2mcvSwIvnx8K6y1euAc1TLVq.jpg', 'https://image.tmdb.org/t/p/original/2Fk3AB8E9dYIBc2ywJkxk8BTyhc.jpg', 'John Garrity, his estranged wife and their young son embark on a perilous journey to find sanctuary as a planet-killing comet hurtles toward Earth. Amid terrifying accounts of cities getting levelled, the Garritys experience the best and worst in humanity. As the countdown to the global apocalypse approaches zero, their incredible trek culminates in a desperate and last-minute flight to a possible safe haven.', NULL, NULL, 16.4076, 7.126, 0, 2.025, '2026-08-07 03:39:39', '2026-08-07 03:39:39');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7993, NULL, NULL, 1985, 'Metal Gear Solid V: The Phantom Pain', 'Metal Gear Solid V: The Phantom Pain', 'game', 2015, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1v85.jpg', NULL, 'Metal Gear Solid V: The Phantom Pain is the sequel to Metal Gear Solid V: Ground Zeroes and a prequel to the original Metal Gear. The game has a complex story with long cut-scene sequences, but there are fewer and they are shorter compared to earlier Metal Gear Solid titles. Most of the gameplay mechanics introduced in Ground Zeroes are carried over: it is still an action game and stealth oriented but replaces the linear corridor design from most earlier titles with large open world environments that offer the player unrestricted freedom for the approach. The world has now a real-time day and night cycle and various weather effects that influence enemy behaviour, visibility and sound. Sabotaging or destroying certain structures can also influence other parts of the map.', 'https://www.igdb.com/games/metal-gear-solid-v-the-phantom-pain', '["PlayStation 3", "PlayStation 4", "PC (Microsoft Windows)", "Xbox 360", "Xbox One"]', NULL, NULL, 0, 7.01500000000000056e+00, '2026-08-07 03:39:39', '2026-08-07 03:39:39');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7994, NULL, NULL, 376, 'Metal Gear Solid 2: Sons of Liberty', 'Metal Gear Solid 2: Sons of Liberty', 'game', 2001, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5e1c.jpg', NULL, 'Metal Gear Solid 2: Sons of Liberty is the sequel to the espionage action game Metal Gear Solid. Much of the gameplay remains the same, as the game''s protagonist has to sneak past guards, outsmart them using various gadgets and defeat the tricky boss enemies. The game expanded its predecessor''s cover mechanic, with Solid Snake or Raiden able to take cover behind walls or objects and pop out to shoot at enemies, while the improved enemy AI allowed enemies to also take cover from the player. Metal Gear Solid 2 is considered to be one of the greatest video games of all time, as well as a leading example of artistic expression in video games.', 'https://www.igdb.com/games/metal-gear-solid-2-sons-of-liberty', '["PlayStation 2"]', NULL, NULL, 0, 11.01, '2026-08-07 03:39:39', '2026-08-07 03:39:39');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7995, 753342, 'tt13287846', NULL, 'Napoleon', 'Napoleon', 'movie', 2023, 'https://image.tmdb.org/t/p/w500/ytFOXyghxLzAM4KZyazDdEkM66q.jpg', 'https://image.tmdb.org/t/p/original/33pMXav77ICRnceEBLhL8lXTywv.jpg', 'An epic that details the checkered rise and fall of French Emperor Napoleon Bonaparte and his relentless journey to power through the prism of his addictive, volatile relationship with his wife, Josephine.', NULL, NULL, 16.6638, 6.304, 0, 10.01, '2026-08-07 03:39:39', '2026-08-07 03:39:39');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7996, 1436, 'tt0275083', NULL, 'The Warrior', '무사', 'movie', 2001, 'https://image.tmdb.org/t/p/w500/i0lpQfqQHN7vEYzSHOk6B65dQbb.jpg', 'https://image.tmdb.org/t/p/original/gUjWplwrg1Nd7KKfzw1nDgzlfpb.jpg', 'In 1375, China was in chaos between Yuan Dynasty and Ming Dynasty. Coryo (an ancient kingdom of Korea then) sent a delegation of many diplomats, soldiers and a silent slave to make peace with the new Chinese government. However, this delegation got charged as spies and sent in exile to a remote desert.', NULL, NULL, 1.8611, 7.034, 0, 10.02, '2026-08-07 03:39:39', '2026-08-07 03:39:39');
