INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8011, 13776, 'tt0083833', NULL, 'Diner', 'Diner', 'movie', 1982, 'https://image.tmdb.org/t/p/w500/2vKIdZ6JkFIzcQeaHg3xtdvOyRO.jpg', 'https://image.tmdb.org/t/p/original/teiop9EWCTTlQ833jrhUPKkK5fs.jpg', 'Set in 1959, Diner shows how five young men resist their adulthood and seek refuge in their beloved Diner. The mundane, childish, and titillating details of their lives are shared. But the golden moments pass, and the men shoulder their responsibilities, leaving the Diner behind.', NULL, NULL, 2.6419, 6.826, 0, 2.04, '2026-08-07 03:39:39', '2026-08-07 03:39:39');
