INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8013, 222899, 'tt1826590', NULL, 'About Last Night', 'About Last Night', 'movie', 2014, 'https://image.tmdb.org/t/p/w500/z3dVYQtxXldDawz7d15wqt2PQLe.jpg', 'https://image.tmdb.org/t/p/original/1wyFgywBCCSnniSOHLlIZijNcty.jpg', 'Bernie and Joan are two fiery flirters who are passionate about everything from hookups to breakups and each other. When he sets up his best friend, Danny, with her roommate, Debbie, the sparks soon fly as they try to navigate the relationship minefields from the bar to the bedroom and are eventually put to the test in the real world.', NULL, NULL, 3.4118, 5.976, 0, 1.01, '2026-08-07 03:39:39', '2026-08-07 03:39:39');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8014, 729830, 'tt4554690', NULL, 'The Automat', 'The Automat', 'movie', 2021, 'https://image.tmdb.org/t/p/w500/7MVOSC8HTtPx9S3T7QeXCggUe1f.jpg', 'https://image.tmdb.org/t/p/original/rb6FW2I8YEuywwQTSYauxCesZu4.jpg', 'The 100-year story of the iconic restaurant chain Horn & Hardart, the inspiration for Starbucks, where generations of Americans ate and drank coffee together at communal tables. From the perspective of former customers, we watch a business climb to its peak success and then grapple with fast food in a forever changed America.', NULL, NULL, 1.1001, 6.8, 0, 1.03, '2026-08-07 03:39:39', '2026-08-07 03:39:39');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8015, 12708, 'tt0056575', NULL, 'That Touch of Mink', 'That Touch of Mink', 'movie', 1962, 'https://image.tmdb.org/t/p/w500/eEG29x9cljGKL2GPmRK9IByyL9e.jpg', 'https://image.tmdb.org/t/p/original/aJaWmyx0sIfVLaLneDdCWqwUiFU.jpg', 'Cathy Timberlake is en route to a job interview when a car transporting businessman Philip Shayne covers her in mud. He sends his assistant, Roger, to apologize, but upon meeting Cathy, Roger knows that she would be a suitable match for his boss. Despite their mutual attraction, Cathy and Philip want different things. Philip wants a fling, while Cathy wants a marriage. As they travel to exotic locales, their differing motivations are put to the test.', NULL, NULL, 2.1767, 6.474, 0, 1.01, '2026-08-07 03:39:39', '2026-08-07 03:39:39');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8016, 8872, 'tt0105793', NULL, 'Wayne''s World', 'Wayne''s World', 'movie', 1992, 'https://image.tmdb.org/t/p/w500/fHwZnFNWR7PaS9t5EBwTvGPeoYQ.jpg', 'https://image.tmdb.org/t/p/original/lAvf5zzyOgTZmpRBRJFa7IVVqCK.jpg', 'The adventures of two amiably aimless metal-head friends, Wayne and Garth. From Wayne''s basement, the pair broadcast a talk-show called "Wayne''s World" on local public access television. The show comes to the attention of a sleazy network executive who wants to produce a big-budget version of "Wayne''s World"—and he also wants Wayne''s girlfriend, a rock singer named Cassandra. Wayne and Garth have to battle the executive not only to save their show, but also Cassandra.', NULL, NULL, 7.1028, 6.684, 0, 1.07, '2026-08-07 03:39:39', '2026-08-07 03:39:39');
