INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8051, 1374, 'tt0089927', NULL, 'Rocky IV', 'Rocky IV', 'movie', 1985, 'https://image.tmdb.org/t/p/w500/2MHUit4H6OK5adcOjnCN6suCKOl.jpg', 'https://image.tmdb.org/t/p/original/uiUb4KJ6tadldqlJme49TW1r3jA.jpg', 'Rocky Balboa holds the world heavyweight championship, but a new challenger has stepped forward: Drago, a six-foot-four, 261-pound fighter who has the backing of the Soviet Union. This time, Rocky''s training regimen takes him to Siberia, where he prepares for a globally televised match in the heart of Moscow. But nothing can truly prepare him for what he''s about to face – a fight to the finish, in which he must defend not only himself, but also the honor of his country!', NULL, NULL, 11.1875, 7.098, 0, 2.055, '2026-08-07 03:39:39', '2026-08-07 03:39:39');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8052, NULL, NULL, 115062, 'Into the Radius', 'Into the Radius', 'game', 2020, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5q1l.jpg', NULL, 'Into the Radius is a single-player survival shooter developed exclusively for premium Virtual Reality headsets. The game is a dark mix of eldritch horror, open-world exploration, realistic weapon handling and intriguing storyline that will make you feel like you''re in the middle of the post-apocalyptic Pechorsk Radius zone.

Life and death intertwine inside the Radius, lurking somewhere in the middle of everything is the answer to a question you can''t quite remember. Through the flickering memories of your tarnished life as a former resident of Pechorsk and now UNSPC specialist, your only means of survival is to stalk the strange and threatening zone and complete the missions assigned to you.

Shoot Fast and Take Cover
Take cover and beware of the threats around you. Gunplay and real bullet physics will keep you on your toes. Featuring classics like the Pistolet Makarova, Double Barrel Shotgun and the AKM Kalashnikov. Weapon interactions are based on their real-life counterparts. Handling, aiming and reloading uses similar movements to their real-world versions.

Weapons have unique ammo and suitable attachments, but must be taken care of or else they will begin to jam!

Interesting Story
Ever since the mysterious and deadly Pechorsk Radius appeared, it had been the single most discussed topic in the media, scientific communities, and political establishments.

Rumors, conspiracies, and legends slowly began to emerge; speaking of wondrous artifacts, deadly anomalies and bizarre entities that inhabit the once quiet mining town.

Today interest has faded, the exclusion zone around the Pechorsk Radius remains completely restricted to the public. Only authorized personnel from the UN Pechorsk Special Committee have any real knowledge of what the Radius truly is.

Hardcore Gameplay
We placed player skill as one of the important focuses of the game. In order to survive inside the Radius you''ll need to pick the right gear for your journey, understand how to navigate the dangerous terrain and discover what kind of anomalies exist, in order to complete your objectives.

Explore Extraordinary Landscapes
Fifteen years after the Pechorsk Event, the Radius has been almost completely abandoned and stands as an isolated and blighted territory. There are miles and miles of forests and crumbling industrial ruins to explore however you want. Be warned, the Radius is filled with lethal anomalies and rumored to contain hostile forces that threaten anyone foolish or daring enough to risk their lives exploring it.', 'https://www.igdb.com/games/into-the-radius', '["Meta Quest 2", "PlayStation VR2", "SteamVR", "Oculus Rift"]', NULL, NULL, 0, 2.03, '2026-08-07 03:39:39', '2026-08-07 03:39:39');
