INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8098, 36290, 'tt0414923', NULL, 'Crimes of Fashion', 'Crimes of Fashion', 'movie', 2004, 'https://image.tmdb.org/t/p/w500/7GEanRXR1tIfSXQlDK9bPZKpaKw.jpg', 'https://image.tmdb.org/t/p/original/qJKm6m3JDG5aqMkzBRiieX8bAt1.jpg', 'Brooke, a plain but creative and hard-working student at the top fashion school in the nation, who has come a long way from her tough childhood spent going from one foster home to another as an orphan. She has always dreamed of becoming a fashion designer, and is thrilled to finally be on her way. But, when the grandfather she never knew about passes away, her life is suddenly turned upside down. Not only has he left her his estate, but he''s left her in charge of the family business, as mob boss to one of the top crime syndicates that has been trying to go legit. If that isn''t enough, the handsome new student she''s falling for is actually an undercover FBI agent aiming to get dirt on her to bring down the family empire.', NULL, NULL, 1.2509, 4.6, 0, 1.01, '2026-08-07 03:39:39', '2026-08-07 03:39:39');
