INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8113, 224633, 'tt2215741', NULL, 'Volume', 'Volume', 'movie', 2012, NULL, NULL, 'Sam lives in a place where everything is polished and secrets are cleaned up and kept. So when Georgina goes missing, everyone acts like nothing happened. But Sam can''t stop thinking about her, the enigma who lived next door, swimming daily in her pool. As Sam drifts back into his memories of Georgina, he comes to realise he may know more than he wants to remember.', NULL, NULL, 1.1012, 7.1, 0, 8.01, '2026-08-07 03:39:39', '2026-08-07 03:39:39');
