INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8116, 22797, 'tt0118804', NULL, 'The Butcher Boy', 'The Butcher Boy', 'movie', 1998, 'https://image.tmdb.org/t/p/w500/9KrClE5Ax6wzCAwgaGRhQI2Eolk.jpg', 'https://image.tmdb.org/t/p/original/bjuH03KlisJ78ssHUzXhruoVulp.jpg', 'Francie and Joe live the usual playful, fantasy filled childhoods of normal boys. However, with a violent, alcoholic father and a manic depressive, suicidal mother the pressure on Francie to grow up are immense. When Francie''s world turns to madness, he tries to counter it with further insanity, with dire consequences.', NULL, NULL, 2.1822, 6.798, 0, 1.02, '2026-08-07 03:39:39', '2026-08-07 03:39:39');
