INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8129, 7300, 'tt0117247', NULL, 'One Fine Day', 'One Fine Day', 'movie', 1996, 'https://image.tmdb.org/t/p/w500/5NiRRR7JDNHOr21JNoGRxPWh9vb.jpg', 'https://image.tmdb.org/t/p/original/5GVVMB1YGU8mNfNK6f3ob1Yt8uR.jpg', 'Melanie Parker, an architect and mother of Sammy, and Jack Taylor, a newspaper columnist and father of Maggie, are both divorced. They meet one morning when overwhelmed Jack is left unexpectedly with Maggie and forgets that Melanie was to take her to school. As a result, both children miss their school field trip and are stuck with the parents. The two adults project their negative stereotypes of ex-spouses on each other, but end up needing to rely on each other to watch the children as each must save his job. Humor is added by Sammy''s propensity for lodging objects in his nose and Maggie''s tendency to wander.', NULL, NULL, 4.1301, 6.478, 0, 1.01, '2026-08-07 03:39:39', '2026-08-07 03:39:39');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8130, 31724, 'tt0994314', NULL, 'Code Geass: Lelouch of the Rebellion', 'コードギアス 反逆のルルーシュ', 'tv', 2006, 'https://image.tmdb.org/t/p/w500/x316WCogkeIwNY4JR8zTCHbI2nQ.jpg', 'https://image.tmdb.org/t/p/original/5hS2OIuZSKGkR8R5l3bY5zh04Ce.jpg', 'Japan has been invaded and conquered by the Britannian Empire. Japan is now known as Area 11 and its citizens known as Elevens. The Britannian Empire takes away Japan''s autonomous power and imposes its rule through the use of Knightmares. The Empire''s rule has never faltered, but cracks have begun to show...', NULL, NULL, 28.4031, 8.344, 0, 1.01, '2026-08-07 03:39:39', '2026-08-07 03:39:39');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8131, 72635, 'tt7124066', NULL, 'Knight''s & Magic', 'ナイツ＆マジック', 'tv', 2017, 'https://image.tmdb.org/t/p/w500/oDzFHkWvZ0JGRsGesVTQE0S7Itu.jpg', 'https://image.tmdb.org/t/p/original/xAiu8FTFW86u3oqrQy8uuZbe60D.jpg', 'A mecha otaku is reincarnated into another world as Ernesti Echevarria, also known as Eru. In this world, huge humanoid weapons known as Silhouette Knights exist. Dreaming of piloting those robots, Eru and his friends, Archid Olter and Adeltrud Olter, aim to become Knight Runners.', NULL, NULL, 8.9034, 7.03, 0, 1.01, '2026-08-07 03:39:39', '2026-08-07 03:39:39');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8132, 61425, 'tt3957232', NULL, 'Cross Ange: Rondo of Angels and Dragons', 'クロスアンジュ 天使と竜の輪舞', 'tv', 2014, 'https://image.tmdb.org/t/p/w500/wUSu7WKW4KfNARFL0eEmdXdqbpn.jpg', 'https://image.tmdb.org/t/p/original/unOzG01uHdlrrRDgQfHLsGFYgsX.jpg', 'Humanity has advanced to great heights since it obtained the information technology known as "Mana." With that nearly magical power, problems like war, food shortages, and pollution have been eliminated. In this age of peace and freedom, First Princess Angelise Ikaruga Misurugi of the Misurugi Empire is a privileged girl with no disabilities. She learns, however, that she is a "Norma," a kind of human who cannot use Mana and are outcasts of society. Having lost everything, she is sent to an isolated island. There she meets other Normas who ride in humanoid weapons called Para-mails, protecting the world from dragon invaders from another dimension.', NULL, NULL, 7.1048, 8.149, 0, 1.01, '2026-08-07 03:39:39', '2026-08-07 03:39:39');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8133, 196400, 'tt15433166', NULL, 'Mobile Suit Gundam: The Witch from Mercury', '機動戦士ガンダム 水星の魔女', 'tv', 2022, 'https://image.tmdb.org/t/p/w500/gBkDlMaAVOVMRWWlRUHhkLAhNE3.jpg', 'https://image.tmdb.org/t/p/original/8A5sNxppHn68k1FtEiEIBTu73yv.jpg', 'A. S. (Ad Stella) 122 ― An era when a multitude of corporations have entered space and built a huge economic system. Suletta Mercury, a lone girl from the remote planet Mercury, transfers to the Asticassia School of Technology, run by the Beneritt Group which dominates the mobile suit industry.', NULL, NULL, 17.1007, 7.4, 0, 1.01, '2026-08-07 03:39:39', '2026-08-07 03:39:39');
