INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8135, 553600, 'tt9116358', NULL, 'Promare', 'プロメア', 'movie', 2019, 'https://image.tmdb.org/t/p/w500/cCVRivpiVUJ4Wn6gHm8pLXppXla.jpg', 'https://image.tmdb.org/t/p/original/f2KgbKxSgOUfHxH434pfpzWC0N1.jpg', 'Galo and the Burning Rescue Fire Department face off against BURNISH, a group of mutants who are able to control and wield flames, and the fire disaster they have unleashed on Earth.', NULL, NULL, 5.4821, 7.049, 0, 1.01, '2026-08-07 03:39:39', '2026-08-07 03:39:39');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8136, 66111, 'tt5827092', NULL, 'Macross Δ', 'マクロスΔ（デルタ）', 'tv', 2016, 'https://image.tmdb.org/t/p/w500/rkhrKOtd6FqG37xGgOhZPTiohBS.jpg', 'https://image.tmdb.org/t/p/original/5sdTl2NpbTS1raycAc2D4b7Atz9.jpg', 'Macross Delta is set in the year 2067, 8 years after the events of  the latest Macross TV series, Macross Frontier. The story focuses on  Walküre, a team of talented idols and the Delta Squadron, a team of  experienced Valkyrie pilots as they battle against the Var Syndrome, a  mysterious phenomena that is consuming the galaxy and there is also the  mysterious Aerial Knights Valkyrie fighter team of the Kingdom of Wind.', NULL, NULL, 5.9044, 6.348, 0, 1.01, '2026-08-07 03:39:39', '2026-08-07 03:39:39');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8137, 21730, 'tt0159193', NULL, 'Mobile Suit Gundam Wing', '新機動戦記ガンダムW', 'tv', 1995, 'https://image.tmdb.org/t/p/w500/ggHmrZpipHfdEqaGQbv4JrWv0f6.jpg', 'https://image.tmdb.org/t/p/original/6q1eredSOpFhzjoStR8V29BxAZC.jpg', 'After Colony (A.C.) 195. Mankind has moved into space. Thousands of people live on giant orbiting space colonies called "Sides." However, the Earth Government, which rules the colonies, is unjust and cruel. A group of revolutionaries builds five robotic weapons called Gundams and plans to send them to Earth to begin their fight for independence. Piloted by five young men, these Gundams carry the hopes and dreams of freedom of the colonists with them as they descend to Earth to begin Operation Meteor!', NULL, NULL, 13.028, 7.842, 0, 1.03, '2026-08-07 03:39:39', '2026-08-07 03:39:39');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8138, 64375, 'tt5344382', NULL, 'Mobile Suit Gundam: Iron-Blooded Orphans', '機動戦士ガンダム 鉄血のオルフェンズ', 'tv', 2015, 'https://image.tmdb.org/t/p/w500/x5M9yxvBhrUP4rsKSl3d9VzK7O.jpg', 'https://image.tmdb.org/t/p/original/52mp7oFltDUkw3kx1ArlRZkLyr3.jpg', 'On a terraformed post-disaster Mars, a group of child security agents rebel against the adults who betrayed them and the oppressive Earth government.', NULL, NULL, 9.3181, 7.5, 0, 1.01, '2026-08-07 03:39:39', '2026-08-07 03:39:39');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8139, 72677, 'tt0159567', NULL, 'Mobile Suit Gundam 0083: Stardust Memory', '機動戦士ガンダム0083 STARDUST MEMORY', 'tv', 1991, 'https://image.tmdb.org/t/p/w500/zLO8bidHA5S26kxI5DufYscgMsU.jpg', 'https://image.tmdb.org/t/p/original/kSwCeAXb6PqaLd2KdwmVCZsW5i0.jpg', 'It is the year 0083 of the Universal Century. The rebellious Principality of Zeon has been defeated in the One Year War by the Earth Federation. However, a faction of Zeon remnants led by Aguille Delaz fled from the final battle, hiding themselves away. After three long years, they attempt to rise up once more, sending Delaz’s ace pilot, Anavel Gato, to infiltrate a Federation research base to steal one of two secretly developed prototype Gundams along with its deadly nuclear warhead.

Threatened by the rogue Gundam suit and seeking to retain peace, the Earth Federation mobilizes the newly developed Albion carrier to recover the stolen unit. Manned by the remaining test pilots, with rookie pilot Kou Uraki piloting the remaining prototype Gundam, the Albion and her crew are determined to stop Gato, retake the stolen Gundam, and prevent the Zeon remnants from starting another war.', NULL, NULL, 7.0401, 7.5, 0, 1.01, '2026-08-07 03:39:39', '2026-08-07 03:39:39');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8140, 13674, 'tt0159186', NULL, 'Mobile Suit Zeta Gundam', '機動戦士Zガンダム', 'tv', 1985, 'https://image.tmdb.org/t/p/w500/dGH9LyV1UMgvbkv1WUEobcTqK5W.jpg', 'https://image.tmdb.org/t/p/original/zK1OaOHgl7dNAE1sKEMXatu2I1s.jpg', 'Universal Century 0087, 7 years have passed since the end of the One Year War between the Earth Federation and the Principality of Zeon. The Earth Federation has created an elite task force, known as the Titans, who are responsible for hunting the remaining Zeon forces. However, the power-hungry Titans have spurred the creation of a rebellious faction called the Anti-Earth Union Group (AEUG).', NULL, NULL, 13.0842, 7.89, 0, 1.01, '2026-08-07 03:39:39', '2026-08-07 03:39:39');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8141, 14571, 'tt0100339', NULL, 'Patlabor: The Movie', '機動警察パトレイバー 劇場版', 'movie', 1989, 'https://image.tmdb.org/t/p/w500/dp3CNNo7Oj704cQKiwM4MJqlW0I.jpg', 'https://image.tmdb.org/t/p/original/h1iPLE2jTWFPKdM8YIDiTgEgbAf.jpg', 'A mysterious suicide and a series of unmanned robot run-aways sparks off a Police investigation into the suspicious software on-board thousands of industrial robots around Tokyo.', NULL, NULL, 2.0767, 6.9, 0, 1.01, '2026-08-07 03:39:39', '2026-08-07 03:39:39');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8142, 35544, 'tt0115263', NULL, 'Martian Successor Nadesico', '機動戦艦ナデシコ', 'tv', 1996, 'https://image.tmdb.org/t/p/w500/iKd4q8iY1mcCCJ0GYBh9uJdlpUn.jpg', 'https://image.tmdb.org/t/p/original/bCTZZyQHkvl8Mfs64m56yU3UdwS.jpg', 'Only one ship stands between earth and total annihilation! The High Mobile Battleship Nadesico is the most formidable fighting machine ever conceived, but due to a shortage of trained soldiers, the crew is a little unorthodox. The poor Jovians don''t stand a chance against the largest contingent of geeks and misfits ever sent into orbit!', NULL, NULL, 6.7325, 6.958, 0, 1.01, '2026-08-07 03:39:39', '2026-08-07 03:39:39');
