INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8153, 105980, 'tt0129023', NULL, 'Dark Harbor', 'Dark Harbor', 'movie', 1999, 'https://image.tmdb.org/t/p/w500/rlOlAcK7dQIA3SE7S1p5jLwCUH6.jpg', 'https://image.tmdb.org/t/p/original/jzmDQsmmAtlOMRl1EmxLtUqzNoY.jpg', 'A bickering couple drive fast through a downpour to catch the last ferry to their island retreat. In a flash, they recognize a crumpled body laying at the side of the road and after much argument they stop, only to find a young man battered and bruised. An offer of summoning the police firmly rejected, the two help the man as best they can although it certainly means missing the ferry... and so starts this thriller: a tale of twisted sexual attraction and ulterior motives.', NULL, NULL, 1.4843, 5.0, 0, 1.01, '2026-08-07 03:39:39', '2026-08-07 03:39:39');
