UPDATE "recommendations" SET "tmdb_id"=993784, "imdb_id"='tt21188080', "igdb_id"=NULL, "title"='Lisa Frankenstein', "original_title"='Lisa Frankenstein', "media_type"='movie', "release_year"=2024, "poster_url"='https://image.tmdb.org/t/p/w500/jAW7ZdIm4HLKB3g15uMOWYNdU8r.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/tsDoiLwZyAbYewoIUDJKk1SJzTF.jpg', "overview"='In 1989, a misunderstood teenager has a high school crush — who just happens to be a handsome corpse! After a set of playfully horrific circumstances bring him back to life, the two embark on a murderous journey to find love, happiness…and a few missing body parts along the way.', "external_url"=NULL, "platforms"=NULL, "popularity"=3.6588, "vote_average"=6.4, "is_ambiguous"=0, "evidence_score"=1.73542857142857158e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-07 03:39:39' WHERE "id"=10;
