UPDATE "recommendations" SET "tmdb_id"=530385, "imdb_id"='tt8772262', "igdb_id"=NULL, "title"='Midsommar', "original_title"='Midsommar', "media_type"='movie', "release_year"=2019, "poster_url"='https://image.tmdb.org/t/p/w500/7LEI8ulZzO5gy9Ww2NVCrKmHeDZ.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/pYgj8e2Y6RufnSyOA6OnzmxFXxZ.jpg', "overview"='Several friends travel to Sweden to study as anthropologists a summer festival that is held every ninety years in the remote hometown of one of them. What begins as a dream vacation in a place where the sun never sets, gradually turns into a dark nightmare as the mysterious inhabitants invite them to participate in their disturbing festive activities.', "external_url"=NULL, "platforms"=NULL, "popularity"=16.9695, "vote_average"=7.148, "is_ambiguous"=0, "evidence_score"=3.52333333333333342e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-07 03:39:39' WHERE "id"=27;
UPDATE "recommendations" SET "tmdb_id"=438631, "imdb_id"='tt1160419', "igdb_id"=NULL, "title"='Dune', "original_title"='Dune', "media_type"='movie', "release_year"=2021, "poster_url"='https://image.tmdb.org/t/p/w500/gDzOcq0pfeCeqMBwKIJlSmQpjkZ.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/qVgZu5BTx6pu4owCvVOm4zjTfOi.jpg', "overview"='Paul Atreides, a brilliant and gifted young man born into a great destiny beyond his understanding, must travel to the most dangerous planet in the universe to ensure the future of his family and his people. As malevolent forces explode into conflict over the planet''s exclusive supply of the most precious resource in existence - a commodity capable of unlocking humanity''s greatest potential - only those who can conquer their fear will survive.', "external_url"=NULL, "platforms"=NULL, "popularity"=32.1831, "vote_average"=7.784, "is_ambiguous"=0, "evidence_score"=3.25546428571428592e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-07 03:39:39' WHERE "id"=30;
