UPDATE "recommendations" SET "tmdb_id"=8967, "imdb_id"='tt0478304', "igdb_id"=NULL, "title"='The Tree of Life', "original_title"='The Tree of Life', "media_type"='movie', "release_year"=2011, "poster_url"='https://image.tmdb.org/t/p/w500/l8cwuB5WJSoj4uMAsnzuHBOMaSJ.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/xq1HIwZq9VbuvMQELAua1nqEkH.jpg', "overview"='The impressionistic story of a Texas family in the 1950s. The film follows the life journey of the eldest son, Jack, through the innocence of childhood to his disillusioned adult years as he tries to reconcile a complicated relationship with his father. Jack finds himself a lost soul in the modern world, seeking answers to the origins and meaning of life while questioning the existence of faith.', "external_url"=NULL, "platforms"=NULL, "popularity"=5.1362, "vote_average"=6.719, "is_ambiguous"=0, "evidence_score"=2.78482608695652196e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-07 03:39:39' WHERE "id"=34;
