UPDATE "recommendations" SET "tmdb_id"=10150, "imdb_id"='tt0084237', "igdb_id"=NULL, "title"='The Last Unicorn', "original_title"='The Last Unicorn', "media_type"='movie', "release_year"=1982, "poster_url"='https://image.tmdb.org/t/p/w500/MRHFtXTjxC74MGCzHACcuqvHiw.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/fwxOQkzYtRVKs3kzcyukdbsyIuh.jpg', "overview"='A unicorn learns from a riddle-speaking butterfly that she is supposedly the last of her kind, all the others having been herded away by the monstrous Red Bull. The unicorn sets out to discover the truth behind the butterfly''s words. She is eventually joined on her quest by Schmendrick, a second-rate magician, and Molly Grue, a middle-aged woman who dreamed all her life of seeing a unicorn. Their journey leads them far from home, all the way to the castle of King Haggard.', "external_url"=NULL, "platforms"=NULL, "popularity"=3.802, "vote_average"=7.283, "is_ambiguous"=0, "evidence_score"=2.89358333333333312e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-07 03:39:39' WHERE "id"=159;
