UPDATE "recommendations" SET "tmdb_id"=14924, "imdb_id"='tt0091954', "igdb_id"=NULL, "title"='Sid and Nancy', "original_title"='Sid and Nancy', "media_type"='movie', "release_year"=1986, "poster_url"='https://image.tmdb.org/t/p/w500/wHzCbMCfipDJ38GW5IyBTWDflMz.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/pLdutWHlPIHf7ldH31akiVLUHQQ.jpg', "overview"='January 1978. After their success in England, the punk rock band Sex Pistols venture out on their tour of the southern United States. Temperamental bassist Sid Vicious is forced by his band mates to travel without his troubled girlfriend, Nancy Spungen, who will meet him in New York. When the band breaks up and Sid begins his solo career in a hostile city, the turbulent couple definitely falls into the depths of drug addiction.', "external_url"=NULL, "platforms"=NULL, "popularity"=3.9814, "vote_average"=6.7, "is_ambiguous"=0, "evidence_score"=10.818, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-07 03:39:39' WHERE "id"=623;
