UPDATE "recommendations" SET "tmdb_id"=10096, "imdb_id"='tt0337563', "igdb_id"=NULL, "title"='13 Going on 30', "original_title"='13 Going on 30', "media_type"='movie', "release_year"=2004, "poster_url"='https://image.tmdb.org/t/p/w500/iNZdSIfhSCMtRILDNyhLn8UKeSG.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/ld7UTOGzZSxIMbuYsb6eQ6QdN4h.jpg', "overview"='After total humiliation at her thirteenth birthday party, Jenna Rink wants to just hide until she''s thirty. Thanks to some magic wishing dust, Jenna''s prayer has been answered. With a knockout body, a fabulous wardrobe, an athlete boyfriend, a dream job, and superstar friends, this can''t be a better life. But soon Jenna realizes that adult life isn’t as easy as she hoped for.', "external_url"=NULL, "platforms"=NULL, "popularity"=8.9045, "vote_average"=6.777, "is_ambiguous"=0, "evidence_score"=1.28708333333333335e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-07 03:39:39' WHERE "id"=667;
