UPDATE "recommendations" SET "tmdb_id"=65086, "imdb_id"='tt1596365', "igdb_id"=NULL, "title"='The Woman in Black', "original_title"='The Woman in Black', "media_type"='movie', "release_year"=2012, "poster_url"='https://image.tmdb.org/t/p/w500/nghQnDZE4EsQJ4J4zxR3UqItTpO.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/jJ3yFKs6xeVGxtmm7GXZYQ3XAvz.jpg', "overview"='The story follows a young lawyer, Arthur Kipps, who is ordered to travel to a remote village and sort out a recently deceased client’s papers. As he works alone in the client’s isolated house, Kipps begins to uncover tragic secrets, his unease growing when he glimpses a mysterious woman dressed only in black. Receiving only silence from the locals, Kipps is forced to uncover the true identity of the Woman in Black on his own, leading to a desperate race against time when he discovers her true identity.', "external_url"=NULL, "platforms"=NULL, "popularity"=3.9988, "vote_average"=6.144, "is_ambiguous"=0, "evidence_score"=1.89459999999999979e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-07 03:39:39' WHERE "id"=849;
