UPDATE "recommendations" SET "tmdb_id"=508442, "imdb_id"='tt2948372', "igdb_id"=NULL, "title"='Soul', "original_title"='Soul', "media_type"='movie', "release_year"=2020, "poster_url"='https://image.tmdb.org/t/p/w500/6jmppcaubzLF8wkXM36ganVISCo.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/rQaHA74pevnGsxcKGaoZVGWe9TC.jpg', "overview"='Joe Gardner is a middle school teacher with a love for jazz music. After a successful audition at the Half Note Club, he suddenly gets into an accident that separates his soul from his body and is transported to the You Seminar, a center in which souls develop and gain passions before being transported to a newborn child. Joe must enlist help from the other souls-in-training, like 22, a soul who has spent eons in the You Seminar, in order to get back to Earth.', "external_url"=NULL, "platforms"=NULL, "popularity"=18.5004, "vote_average"=8.089, "is_ambiguous"=0, "evidence_score"=12.525, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-07 03:39:39' WHERE "id"=1240;
