UPDATE "recommendations" SET "tmdb_id"=9544, "imdb_id"='tt0295254', "igdb_id"=NULL, "title"='FearDotCom', "original_title"='FearDotCom', "media_type"='movie', "release_year"=2002, "poster_url"='https://image.tmdb.org/t/p/w500/phcd5AJvA1S45JMKYoNLhTzFwsE.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/5gnBqLDi1pjJxxCgpOJCu5VSLp1.jpg', "overview"='When four bodies are discovered among the industrial decay and urban grime of New York City, brash young detective Mike Reilly teams with ambitious Department of Health researcher Terry Huston to uncover the cause behind their violent and inexplicable deaths. The only common factor shared by the victims? Each died exactly 48 hours after logging onto a website called feardotcom.', "external_url"=NULL, "platforms"=NULL, "popularity"=3.2457, "vote_average"=3.808, "is_ambiguous"=0, "evidence_score"=6.51500000000000056e+00, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-07 03:39:39' WHERE "id"=1346;
