UPDATE "recommendations" SET "tmdb_id"=34584, "imdb_id"='tt0088323', "igdb_id"=NULL, "title"='The NeverEnding Story', "original_title"='Die unendliche Geschichte', "media_type"='movie', "release_year"=1984, "poster_url"='https://image.tmdb.org/t/p/w500/ddYCa91iDXfJCxaqSYzwi2fjfnl.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/rKmOe5pb5a6P1HmQAzpRw20gORp.jpg', "overview"='While hiding from bullies in his school''s attic, a young boy discovers the extraordinary land of Fantasia, through a magical book called The Neverending Story. The book tells the tale of Atreyu, a young warrior who, with the help of a luck dragon named Falkor, must save Fantasia from the destruction of The Nothing.', "external_url"=NULL, "platforms"=NULL, "popularity"=7.8998, "vote_average"=7.224, "is_ambiguous"=0, "evidence_score"=3.81702941176470602e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-07 03:39:39' WHERE "id"=2085;
