UPDATE "recommendations" SET "tmdb_id"=5967, "imdb_id"='tt0058450', "igdb_id"=NULL, "title"='The Umbrellas of Cherbourg', "original_title"='Les Parapluies de Cherbourg', "media_type"='movie', "release_year"=1964, "poster_url"='https://image.tmdb.org/t/p/w500/tAgTf64XKK5ir7w5C7dnB53jWWG.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/m1Gei9O5GfLoJHQjBaxWBSkXX2y.jpg', "overview"='This simple romantic tragedy begins in 1957. Guy Foucher, a 20-year-old French auto mechanic, has fallen in love with 17-year-old Geneviève Emery, an employee in her widowed mother''s chic but financially embattled umbrella shop. On the evening before Guy is to leave for a two-year tour of combat in Algeria, he and Geneviève make love. She becomes pregnant and must choose between waiting for Guy''s return or accepting an offer of marriage from a wealthy diamond merchant.', "external_url"=NULL, "platforms"=NULL, "popularity"=2.701, "vote_average"=7.386, "is_ambiguous"=0, "evidence_score"=12.92, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-07 03:39:39' WHERE "id"=2098;
