UPDATE "recommendations" SET "tmdb_id"=1417, "imdb_id"='tt0457430', "igdb_id"=NULL, "title"='Pan''s Labyrinth', "original_title"='El laberinto del fauno', "media_type"='movie', "release_year"=2006, "poster_url"='https://image.tmdb.org/t/p/w500/z7xXihu5wHuSMWymq5VAulPVuvg.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/6G6nqSW9S7EHA9HrYl0Z8uo2H7f.jpg', "overview"='In post–civil war Spain, 10-year-old Ofelia moves with her pregnant mother to live under the control of her cruel stepfather. Drawn into a mysterious labyrinth, she meets a faun who reveals that she may be a lost princess from an underground kingdom. To return to her true father, she must complete a series of surreal and perilous tasks that blur the line between reality and fantasy.', "external_url"=NULL, "platforms"=NULL, "popularity"=16.456, "vote_average"=7.766, "is_ambiguous"=0, "evidence_score"=3.70922580645161303e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-07 03:39:39' WHERE "id"=2112;
