UPDATE "recommendations" SET "tmdb_id"=9637, "imdb_id"='tt0267913', "igdb_id"=NULL, "title"='Scooby-Doo', "original_title"='Scooby-Doo', "media_type"='movie', "release_year"=2002, "poster_url"='https://image.tmdb.org/t/p/w500/mTAiBJGg8mqEfnYHHbi37ZoRSZm.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/1RAxtBxslR4OZCZC1vxIRUxjR7a.jpg', "overview"='When the Mystery Inc. gang is invited to Spooky Island, a popular amusement park, they soon discover that the attractions aren''t the only things that are spooky. Strange things are happening, and it''s up to Scooby, Shaggy, Fred, Daphne, and Velma to uncover the truth behind the mysterious happenings.', "external_url"=NULL, "platforms"=NULL, "popularity"=12.9225, "vote_average"=6.113, "is_ambiguous"=0, "evidence_score"=13.31625, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-07 03:39:39' WHERE "id"=2117;
