UPDATE "recommendations" SET "tmdb_id"=4147, "imdb_id"='tt0257044', "igdb_id"=NULL, "title"='Road to Perdition', "original_title"='Road to Perdition', "media_type"='movie', "release_year"=2002, "poster_url"='https://image.tmdb.org/t/p/w500/loSpBeirRfTPJ3cMIqpQArstGhh.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/cDDyZ2qtBzNAepdTbgxKfFcxREl.jpg', "overview"='Mike Sullivan works as a hit man for crime boss John Rooney. Sullivan views Rooney as a father figure, however after his son is witness to a killing, Mike Sullivan finds himself on the run in attempt to save the life of his son and at the same time looking for revenge on those who wronged him.', "external_url"=NULL, "platforms"=NULL, "popularity"=4.6873, "vote_average"=7.361, "is_ambiguous"=0, "evidence_score"=1.67442857142857128e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-07 03:39:39' WHERE "id"=2340;
