UPDATE "recommendations" SET "tmdb_id"=4922, "imdb_id"='tt0421715', "igdb_id"=NULL, "title"='The Curious Case of Benjamin Button', "original_title"='The Curious Case of Benjamin Button', "media_type"='movie', "release_year"=2008, "poster_url"='https://image.tmdb.org/t/p/w500/26wEWZYt6yJkwRVkjcbwJEFh9IS.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/2fswjyrY3GEzeoVn6mF8pNeNcgf.jpg', "overview"='Born under unusual circumstances, Benjamin Button springs into being as an elderly man in a New Orleans nursing home and ages in reverse. Twelve years after his birth, he meets Daisy, a child who flits in and out of his life as she grows up to be a dancer. Though he has all sorts of unusual adventures over the course of his life, it is his relationship with Daisy, and the hope that they will come together at the right time, that drives Benjamin forward.', "external_url"=NULL, "platforms"=NULL, "popularity"=12.6498, "vote_average"=7.601, "is_ambiguous"=0, "evidence_score"=1.12971428571428571e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-07 03:39:39' WHERE "id"=2344;
