UPDATE "recommendations" SET "tmdb_id"=NULL, "imdb_id"=NULL, "igdb_id"=36952, "title"='Wolfenstein II: The New Colossus', "original_title"='Wolfenstein II: The New Colossus', "media_type"='game', "release_year"=2017, "poster_url"='https://images.igdb.com/igdb/image/upload/t_cover_big/co21c5.jpg', "backdrop_url"=NULL, "overview"='Wolfenstein II: The New Colossus is the eleventh installment of the Wolfenstein series and a sequel to the 2014''s Wolfenstein: The New Order. The game follows the main protagonist, William Joseph "B.J." Blazkowicz, in his efforts to ignite a Second American Revolution.

