UPDATE "recommendations" SET "tmdb_id"=121, "imdb_id"='tt0167261', "igdb_id"=NULL, "title"='The Lord of the Rings: The Two Towers', "original_title"='The Lord of the Rings: The Two Towers', "media_type"='movie', "release_year"=2002, "poster_url"='https://image.tmdb.org/t/p/w500/5VTN0pR8gcqV3EPUHHfMGnJYN9L.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/kWYfW2Re0rUDE6IHhy4CRuKWeFr.jpg', "overview"='Frodo Baggins and the other members of the Fellowship continue on their sacred quest to destroy the One Ring--but on separate paths. Their destinies lie at two towers--Orthanc Tower in Isengard, where the corrupt wizard Saruman awaits, and Sauron''s fortress at Barad-dur, deep within the dark lands of Mordor. Frodo and Sam are trekking to Mordor to destroy the One Ring of Power while Gimli, Legolas and Aragorn search for the orc-captured Merry and Pippin. All along, nefarious wizard Saruman awaits the Fellowship members at the Orthanc Tower in Isengard.', "external_url"=NULL, "platforms"=NULL, "popularity"=41.5668, "vote_average"=8.425, "is_ambiguous"=0, "evidence_score"=5.34, "created_at"='2026-07-21 03:32:24', "updated_at"='2026-08-07 03:39:39' WHERE "id"=4773;
