UPDATE "recommendations" SET "tmdb_id"=3777, "imdb_id"='tt0050613', "igdb_id"=NULL, "title"='Throne of Blood', "original_title"='蜘蛛巣城', "media_type"='movie', "release_year"=1957, "poster_url"='https://image.tmdb.org/t/p/w500/zaZFMNxJST0TtPd68yF7fNt1he8.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/rohRr9XqTRF8YwLMGAnTprg3GnL.jpg', "overview"='Returning to their lord''s castle, samurai warriors Washizu and Miki are waylaid by a spirit who predicts their futures. When the first part of the spirit''s prophecy comes true, Washizu''s scheming wife, Asaji, presses him to speed up the rest of the spirit''s prophecy by murdering his lord and usurping his place. Director Akira Kurosawa''s resetting of William Shakespeare''s "Macbeth" in feudal Japan is one of his most acclaimed films.', "external_url"=NULL, "platforms"=NULL, "popularity"=4.9669, "vote_average"=7.921, "is_ambiguous"=0, "evidence_score"=7.01, "created_at"='2026-07-21 03:32:24', "updated_at"='2026-08-07 03:39:39' WHERE "id"=4919;
