UPDATE "recommendations" SET "tmdb_id"=93856, "imdb_id"='tt1991245', "igdb_id"=NULL, "title"='Chernobyl Diaries', "original_title"='Chernobyl Diaries', "media_type"='movie', "release_year"=2012, "poster_url"='https://image.tmdb.org/t/p/w500/9AKhThGA8IATBy3gR7I4dw9SEc4.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/1BgWRWjZtD6zyJfzlfDx3NHaECQ.jpg', "overview"='A group of six tourists looking to go off the beaten path, hire an ''extreme tour guide'' who, ignoring warnings, takes them into the city of Pripyat, the former home to the workers of the Chernobyl nuclear reactor, but now a deserted town since the disaster more than 25 years earlier. After a brief exploration of the abandoned city, the group members find themselves stranded, only to discover that they are not alone.', "external_url"=NULL, "platforms"=NULL, "popularity"=3.8068, "vote_average"=5.325, "is_ambiguous"=0, "evidence_score"=5.012, "created_at"='2026-07-21 03:32:24', "updated_at"='2026-08-07 03:39:39' WHERE "id"=4985;
