UPDATE "recommendations" SET "tmdb_id"=10184, "imdb_id"='tt1001508', "igdb_id"=NULL, "title"='He''s Just Not That Into You', "original_title"='He''s Just Not That Into You', "media_type"='movie', "release_year"=2009, "poster_url"='https://image.tmdb.org/t/p/w500/jip2ap24Y6JxEgzVRyNqyYssnyR.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/jZkkch6yrP1tVVfEU2uqwej9rBM.jpg', "overview"='Have you ever wondered why they said they would call but didn''t, or why they don''t want to sleep with you anymore, or why your relationship isn''t going to the next level? Maybe they''re just not that into you. Gigi wants a man who says he''ll call her - and actually does - while Alex advises her to stop waiting by the phone. Beth wants a proposal after years of a committed relationship with her boyfriend, Neil, who is just fine with the way things are. Janine''s not sure if she can trust her husband, Ben, who can''t quite trust himself around Anna. Anna can''t decide between the sexy married guy or her straightforward, no-sparks standby, Conor, who can''t get over the fact that he can''t have her. And Mary, who''s found an entire network of loving, supportive men, just needs to find one who''s straight.', "external_url"=NULL, "platforms"=NULL, "popularity"=8.3181, "vote_average"=6.625, "is_ambiguous"=0, "evidence_score"=7.01, "created_at"='2026-07-29 20:51:09', "updated_at"='2026-08-07 03:39:39' WHERE "id"=5181;
