UPDATE "recommendations" SET "tmdb_id"=4497, "imdb_id"='tt0055601', "igdb_id"=NULL, "title"='Viridiana', "original_title"='Viridiana', "media_type"='movie', "release_year"=1962, "poster_url"='https://image.tmdb.org/t/p/w500/mYPuSx5JwL8AdTwS1iQW4Un1cYP.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/2QGuTuyxwCCER9iwSeONW8BAxce.jpg', "overview"='Viridiana is preparing to start her life as a nun when she is sent, somewhat unwillingly, to visit her aging uncle, Don Jaime. He supports her; but the two have met only once. Jaime thinks Viridiana resembles his dead wife. Viridiana has secretly despised this man all her life and finds her worst fears proven when Jaime grows determined to seduce his pure niece. Viridiana becomes undone as her uncle upends the plans she had made to join the convent.', "external_url"=NULL, "platforms"=NULL, "popularity"=1.8622, "vote_average"=7.7, "is_ambiguous"=0, "evidence_score"=2.045, "created_at"='2026-08-03 14:31:56', "updated_at"='2026-08-07 03:39:39' WHERE "id"=6640;
