UPDATE "recommendations" SET "tmdb_id"=18837, "imdb_id"='tt2330912', "igdb_id"=NULL, "title"='Macross Plus: The Movie', "original_title"='マクロスプラス MOVIE EDITION', "media_type"='movie', "release_year"=1995, "poster_url"='https://image.tmdb.org/t/p/w500/kwx4ogFB0ST3jAHAuda9xFF2tnW.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/pAsOHBxDazz9BTqigU0pRg2PkoG.jpg', "overview"='Three decades after the great war between the humans and the Zentradi, the U.N. government is developing new technologies to use in their transforming fighter aircraft by running tests on the colony planet Eden. Military test pilots and former childhood friends, loose cannon Isamu Alva Dyson and the Zentradi mixed race Guld Goa Bowman, are selected to each pilot a new aircraft (Shinsei Industries'' YF-19 & General Galaxy''s YF-21) for Project Super Nova, to choose the newest successor to the VF-11 Thunderbolt variable fighter which is currently still in use by the U.N. Spacy military forces. Their own personal grudges end up disrupting the tests, and begin to wreak havoc on the program.', "external_url"=NULL, "platforms"=NULL, "popularity"=2.5571, "vote_average"=7.1, "is_ambiguous"=0, "evidence_score"=6.045, "created_at"='2026-08-03 14:31:56', "updated_at"='2026-08-07 03:39:39' WHERE "id"=6681;
