UPDATE "recommendations" SET "tmdb_id"=169219, "imdb_id"='tt1905040', "igdb_id"=NULL, "title"='The Dyatlov Pass Incident', "original_title"='The Dyatlov Pass Incident', "media_type"='movie', "release_year"=2013, "poster_url"='https://image.tmdb.org/t/p/w500/8hyvniwVeSvKbTNKrY44ndMsQht.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/j5iUZRZtaPJbYJxvB6ZtmbE5LsZ.jpg', "overview"='In February of 1959, nine Russian hikers ventured into a remote area of the Ural Mountains. Two weeks later, all of them were found dead. What happened is a mystery that has baffled investigators and researchers for decades. It has become known as the Dyatlov Pass Incident.  When five ambitious American college students are issued a grant to return to the site of the original events, they gear up with the belief that they can uncover and document the truth of what happened to the supposedly experienced hikers. But what they find is more shocking than anything they could have imagined. Retracing the steps of the Russians'' ill-fated journey, the students are plagued by strange and increasingly terrifying phenomena that suggest that in spite of the desolate surroundings, they are not alone. The forces at work in the Dyatlov Pass Incident have been waiting for them.', "external_url"=NULL, "platforms"=NULL, "popularity"=2.5765, "vote_average"=5.95, "is_ambiguous"=0, "evidence_score"=5.7, "created_at"='2026-08-04 03:20:13', "updated_at"='2026-08-07 03:39:39' WHERE "id"=7198;
