UPDATE "recommendations" SET "tmdb_id"=1272851, "imdb_id"=NULL, "igdb_id"=NULL, "title"='I Hit a Man', "original_title"='Сбила человечка', "media_type"='movie', "release_year"=2023, "poster_url"=NULL, "backdrop_url"=NULL, "overview"='Lena, a popular Instagram blogger, knocks down a man on the way to a country cottage. To hide the incident, she turns to her young man Lesha and his friends, Pasha and Andrei, for help. Arriving at the scene of the accident, Lesha''s friends discover that the downed man is singer Ilya Korkin, their idol. Long-term friendship does not stand up to such a test, only a miracle can help a couple. Andrey, before the final breakup with Lesha, shares the contact of the Cleaner, who will help cover his tracks. The arriving professional examines the body and recognizes Ilya Korkin, whose songs are for him a ray of light in his dark world. He faces a dilemma – to do his job or avenge the death of his beloved singer.', "external_url"=NULL, "platforms"=NULL, "popularity"=0.71, "vote_average"=8.0, "is_ambiguous"=0, "evidence_score"=5.56000000000000049e+00, "created_at"='2026-08-05 03:13:48', "updated_at"='2026-08-07 03:39:39' WHERE "id"=7588;
